Yes — the max batch size is **5,000 events**. Sending **10,000** per request is likely contributing to failures.

## Batch limit
- **Max batch size:** 5,000
- **Recommended batch size:** 1,000
- Above 5,000, requests may fail with **413** or **422** depending on size and validation overhead

## JavaScript serializer example
```js
const EVENT_TYPE_MAP = {
  view: 'view',
  page_view: 'view',
  click: 'click',
  page_click: 'click',
  signup: 'signup',
  purchase: 'purchase',
  cancel: 'cancel'
};

function toRFC3339(value) {
  const d = new Date(value);
  if (Number.isNaN(d.getTime())) throw new Error('Invalid timestamp');
  return d.toISOString();
}

function normalizeEvent(event) {
  const rawType = String(event.event_type || '').trim().toLowerCase();
  const mappedType = EVENT_TYPE_MAP[rawType];
  if (!mappedType) throw new Error(`Invalid event_type: ${event.event_type}`);

  if (!event.source) throw new Error('source cannot be null');

  return {
    ...event,
    event_type: mappedType,
    timestamp: toRFC3339(event.timestamp)
  };
}

function chunkEvents(events, size = 1000) {
  const chunks = [];
  for (let i = 0; i < events.length; i += size) {
    chunks.push(events.slice(i, i + size));
  }
  return chunks;
}
```

## Recommendation
Split your 10,000 events into **10 batches of 1,000**.

If you want, I can also help you add **retry logic** for the failed chunks.

{"status":"success","data":{"code":"async function sendBatch(client, events) {
  const normalized = [];
  const errors = [];

  for (const event of events) {
    try {
      normalized.push(normalizeEvent(event));
    } catch (err) {
      errors.push({ event_id: event.event_id || null, error: err.message });
    }
  }

  if (normalized.length === 0) return { sent: 0, errors };

  const chunks = chunkEvents(normalized, 1000);
  const results = [];

  for (const chunk of chunks) {
    const res = await client.post('/v2/ingest/events', chunk);
    results.push(res.data);
  }

  return { sent: normalized.length, errors, results };
}","note":"Assumes normalizeEvent() and chunkEvents() are defined as previously shown."}}

Here’s a minimal **Node.js wrapper** you can use:

```js
async function sendBatch(client, events) {
  const normalized = [];
  const errors = [];

  for (const event of events) {
    try {
      normalized.push(normalizeEvent(event));
    } catch (err) {
      errors.push({ event_id: event.event_id || null, error: err.message });
    }
  }

  if (normalized.length === 0) return { sent: 0, errors };

  const chunks = chunkEvents(normalized, 1000);
  const results = [];

  for (const chunk of chunks) {
    const res = await client.post('/v2/ingest/events', chunk);
    results.push(res.data);
  }

  return { sent: normalized.length, errors, results };
}
```

