Yes — retries are configurable.

### Retry policy
- **Default:** 5 attempts
- **Configurable:** **yes**
- **Allowed range:** **3 to 8 attempts**
- **Backoff:** exponential with jitter

So your requested **3 attempts** is valid.

---

## Node.js HMAC verification example

```js
import crypto from 'crypto';
import express from 'express';

const app = express();

// Important: use raw body for signature verification
app.use('/webhooks/proplink', express.raw({ type: 'application/json' }));

const WEBHOOK_SECRET = process.env.WEBHOOK_SECRET;
const MAX_SKEW_SECONDS = 300;

function timingSafeEqual(a, b) {
  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');
  if (bufA.length !== bufB.length) return false;
  return crypto.timingSafeEqual(bufA, bufB);
}

app.post('/webhooks/proplink', (req, res) => {
  const signature = req.header('X-PropLink-Signature');
  const timestamp = req.header('X-PropLink-Timestamp');
  const eventId = req.header('X-PropLink-Event-Id');

  if (!signature || !timestamp || !eventId) {
    return res.status(400).send('Missing required headers');
  }

  const ts = Number(timestamp);
  const now = Math.floor(Date.now() / 1000);
  if (!Number.isFinite(ts) || Math.abs(now - ts) > MAX_SKEW_SECONDS) {
    return res.status(401).send('Timestamp outside tolerance window');
  }

  const rawBody = req.body.toString('utf8');
  const signedPayload = `${timestamp}.${rawBody}`;
  const expected = crypto
    .createHmac('sha256', WEBHOOK_SECRET)
    .update(signedPayload, 'utf8')
    .digest('hex');

  if (!timingSafeEqual(signature, expected)) {
    return res.status(401).send('Invalid signature');
  }

  // TODO: idempotency check by eventId
  // TODO: process event_sequence ordering per tenant/object type

  return res.status(200).json({ ok: true });
});

app.listen(3000, () => {
  console.log('Webhook listener running on port 3000');
});
```

### Implementation notes
- Use **raw body**; don’t parse JSON before verifying
- Store processed `event_id` values for idempotency
- Enforce ordering only where your business logic requires it
- Keep the tolerance window tight enough to reduce replay risk

---

