            timeout=10
        )
        resp.raise_for_status()

        logger.info('hubspot_update_success', extra={'email': email, 'course': course_title})
        return {'statusCode': 200, 'body': json.dumps({'status': 'success'})}

    except requests.Timeout:
        logger.exception('hubspot_timeout')
        return {'statusCode': 504, 'body': json.dumps({'error': 'upstream timeout'})}
    except requests.HTTPError as e:
        logger.exception('hubspot_http_error')
        return {'statusCode': 502, 'body': json.dumps({'error': 'hubspot update failed', 'detail': str(e)})}
    except Exception as e:
        logger.exception('unexpected_error')
        return {'statusCode': 500, 'body': json.dumps({'error': 'internal error', 'detail': str(e)})}
```

